import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`bookkeeping-proposal`,heroTitle:`Generate bookkeeping proposals in minutes`,heroSubtitle:`Perplexity Computer analyzes your client notes, scopes the monthly work, and drafts a recurring bookkeeping proposal with pricing automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your client notes`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded bookkeeping discovery notes, financial files, or client intake docs. Build a complete bookkeeping proposal. (1) Extract the business type, transaction volume, entities, systems, close requirements, reporting cadence, and pain points from the uploaded materials. (2) Recommend the right bookkeeping scope, including monthly close, reconciliations, AP or AR support, reporting, and controller-level add-ons where relevant. (3) Build pricing options with implementation fees, monthly retainers, and optional services. (4) Draft proposal sections for current-state issues, recommended scope, deliverables, timeline, and communication cadence. (5) Flag any assumptions or missing information that should be confirmed before sending. (6) Deliver a polished bookkeeping proposal that is ready to share with the prospect.`,heroOverlaySteps:[`Extracting business details, systems, reporting needs, and close complexity from your files`,`Scoping the monthly bookkeeping work and implementation requirements`,`Building pricing options, deliverables, and proposal sections`,`Recurring bookkeeping proposal ready to review and send`],generatingSteps:[`Reading the uploaded intake docs, financial files, and discovery notes`,`Designing an agent to translate client needs into a clear bookkeeping scope`,`Configuring pricing logic, implementation assumptions, and service options`,`Preparing a polished bookkeeping proposal with deliverables and next steps`],featureSectionTitle:`From client intake to recurring retainer proposal`,featureCardTitles:[`Connects to your firm workflow`,`Proposals built for recurring revenue`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Sheets, docs, CRM notes, and internal review workflows stay connected so proposal drafting and pricing move faster.`,`Service scope. Monthly pricing. Implementation fees. Delivery cadence. Computer gives your firm a proposal draft that is ready for client review.`],capabilitySectionTitle:`Your proposal desk, on autopilot`,capabilitySectionSubtitle:`Upload your discovery notes, get back a bookkeeping proposal built for a recurring engagement.`,capabilityCards:[{title:`Client Discovery Analysis`,description:`Computer can extract transaction volume, systems, reporting needs, and close complexity from client notes and uploaded financial files.`},{title:`Service Packaging`,description:`Computer can recommend the right bookkeeping scope across reconciliations, close, reporting, AP or AR support, and optional controller services.`},{title:`Pricing Model`,description:`Computer can build monthly retainers, implementation fees, and add-on pricing so you can present clear options without rebuilding the proposal each time.`},{title:`Connect Your Tools`,description:`Computer can organize proposal drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred deliverables, pricing guardrails, and proposal structure across sessions so every draft stays consistent.`},{title:`Renewal & Upsell Plays`,description:`Computer can suggest additional services and future reporting upgrades so bookkeeping proposals create room for expansion over time.`}]});export{t as default};
